package com.rpsbattle.tournament.coding;
import com.rpsbattle.auth.AuthException;
import com.rpsbattle.bot.ownership.*;
import com.rpsbattle.bot.upload.*;
import com.rpsbattle.tournament.domain.*;
import jakarta.persistence.*;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.*;
import java.time.Instant;
import java.util.*;

@Repository
public class SubmissionStore {
 @org.springframework.beans.factory.annotation.Autowired FinalValidationStore timelineFinals;
 /** Explicit manager-authorized new coding window; old versions/freezes remain immutable. */
 @Transactional public void reopenTimeline(Tournament t,UUID actor){UUID tid=UUID.fromString(t.id);db.createNativeQuery("select id from coding_queue_guard where id=1 for update").getSingleResult();db.createNativeQuery("update bot_coding_jobs set status='FAILED',finished_at=CURRENT_TIMESTAMP where workspace_id in (select id from tournament_code_workspaces where tournament_id=:t) and status in ('QUEUED','RUNNING')").setParameter("t",tid).executeUpdate();invalidateAttempts(tid);timelineFinals.suspendForExtension(tid);for(var s:db.createQuery("select s from BotSubmission s where s.tournamentId=:t",BotSubmission.class).setParameter("t",tid).getResultList()){s.status="REJECTED";audit(tid,actor,"ALLOW-RESUBMIT",s.versionId,"TIMELINE_EXTENDED");}for(var w:db.createQuery("select w from CodeWorkspace w where w.tournamentId=:t",CodeWorkspace.class).setParameter("t",tid).getResultList()){w.status="DRAFT";w.currentVersionId=null;w.touch();}}
 private void invalidateAttempts(UUID tournament){for(var attempt:db.createQuery("select a from SubmissionAttempt a where a.tournamentId=:t and a.status in ('QUEUED','BUILDING','TESTING','FINALIZING')",SubmissionAttempt.class).setParameter("t",tournament).getResultList()){attempt.status="FAILED";attempt.errorCode="CODING_WINDOW_CHANGED";attempt.errorDetail="Ban tổ chức đã mở lại cửa lập trình. Kiểm tra bài và nộp lại trong cửa mới.";attempt.finishedAt=attempt.updatedAt=Instant.now();var v=db.find(CodeVersion.class,attempt.versionId);v.status="TEST_FAILED";v.updatedAt=attempt.finishedAt;}}
 @PersistenceContext EntityManager db;
 private final BotUploadService uploads;private final BotRepository bots;private final WorkspaceSandbox sandbox;
 @org.springframework.beans.factory.annotation.Autowired CodingQueueStore queue;
 public SubmissionStore(BotUploadService uploads,BotRepository bots,WorkspaceSandbox sandbox){this.uploads=uploads;this.bots=bots;this.sandbox=sandbox;}
 @Transactional public void enable(String id){UUID t=UUID.fromString(id);if(!enabled(id))db.createNativeQuery("insert into tournament_coding_enrollment(tournament_id) values(:t)").setParameter("t",t).executeUpdate();}
 @Transactional(readOnly=true) public boolean enabled(String id){return ((Number)db.createNativeQuery("select count(*) from tournament_coding_enrollment where tournament_id=:t").setParameter("t",UUID.fromString(id)).getSingleResult()).intValue()>0;}
 private BotSubmission submission(UUID t,UUID user,boolean lock){var q=db.createQuery("select s from BotSubmission s where s.tournamentId=:t and s.userId=:u",BotSubmission.class).setParameter("t",t).setParameter("u",user);if(lock)q.setLockMode(LockModeType.PESSIMISTIC_WRITE);return q.getResultStream().findFirst().orElse(null);}
 public record Summary(UUID id,UUID userId,UUID registrationId,String sourceType,String language,int version,String status,String build,String tests,UUID versionId,String artifactHash,Instant submittedAt,Instant lockedAt){}
 private Summary summary(BotSubmission s){var v=db.find(CodeVersion.class,s.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId);return new Summary(s.id,s.userId,s.registrationId,s.sourceType,w.language,v.number,s.status,v.status,(v.publicPassed&&(v.pipelineSubmission||v.samplePassed))?"PASS":"FAIL",v.id,s.artifactHash,s.submittedAt,s.lockedAt);}
 @Transactional(readOnly=true) public Summary mine(String id,UUID user){var s=submission(UUID.fromString(id),user,false);return s==null?null:summary(s);}
 @Transactional(readOnly=true) public Summary detail(String id,UUID submissionId){var s=db.find(BotSubmission.class,submissionId);if(s==null||!s.tournamentId.toString().equals(id))throw new AuthException("SUBMISSION_NOT_FOUND",404);return summary(s);}
 @Transactional(readOnly=true) public List<Summary> dashboard(String id,int page){return db.createQuery("select s from BotSubmission s where s.tournamentId=:t order by s.submittedAt desc,s.id",BotSubmission.class).setParameter("t",UUID.fromString(id)).setFirstResult(page*25).setMaxResults(25).getResultStream().map(this::summary).toList();}
 @Transactional(readOnly=true) public List<Map<String,Object>> versions(String id,UUID user){return db.createQuery("select v from CodeVersion v,CodeWorkspace w where v.workspaceId=w.id and w.tournamentId=:t and w.userId=:u order by v.createdAt desc",CodeVersion.class).setParameter("t",UUID.fromString(id)).setParameter("u",user).setMaxResults(100).getResultStream().map(v->{var w=db.find(CodeWorkspace.class,v.workspaceId);var row=new LinkedHashMap<String,Object>();row.put("id",v.id);row.put("number",v.number);row.put("language",w.language);row.put("status",v.status);row.put("sourceHash",v.sourceHash);row.put("artifactHash",Objects.toString(v.artifactHash,""));row.put("createdAt",v.createdAt);var attempt=db.createQuery("select a from SubmissionAttempt a where a.versionId=:v",SubmissionAttempt.class).setParameter("v",v.id).getResultStream().findFirst();attempt.ifPresent(a->{row.put("attemptStatus",a.status);row.put("errorCode",Objects.toString(a.errorCode,""));row.put("errorDetail",Objects.toString(a.errorDetail,""));});return (Map<String,Object>)row;}).toList();}
 public record Selection(CodeWorkspace w,CodeVersion v){}
 private Selection selection(UUID t,UUID user,String language,UUID versionId){var v=versionId==null?null:db.find(CodeVersion.class,versionId);var w=v==null?null:db.find(CodeWorkspace.class,v.workspaceId,LockModeType.PESSIMISTIC_WRITE);if(w==null||!w.tournamentId.equals(t)||!w.userId.equals(user)||language!=null&&!w.language.equals(language))throw new AuthException("VERSION_NOT_OWNED",403);return new Selection(w,v);}
 @Transactional public TournamentRegistration submit(Tournament t,UUID user,UUID versionId,boolean automatic){return promote(t,user,versionId,automatic,false);}
 private TournamentRegistration promote(Tournament t,UUID user,UUID versionId,boolean automatic,boolean deadline){
  UUID tid=UUID.fromString(t.id);db.createNativeQuery("select id from users where id=:id for update").setParameter("id",user).getSingleResult();var selected=selection(tid,user,null,versionId);var w=selected.w;var v=selected.v;
  if(!deadline&&w.busy()||!v.status.equals("READY")||!v.publicPassed||!v.pipelineSubmission&&!v.samplePassed||t.botPolicy.hiddenTestsEnabled()&&!v.hiddenPassed||v.artifactHash==null)throw new AuthException("SUBMISSION_NOT_READY",409);
  if(!t.botPolicy.allowedLanguages().contains(w.language))throw new AuthException("BOT_LANGUAGE_NOT_ALLOWED",400);
  boolean imported=v.importedBotId!=null;if(imported&&t.botPolicy.submissionMode()==BotSubmissionMode.CODE_IN_PLATFORM_ONLY||!imported&&t.botPolicy.submissionMode()==BotSubmissionMode.PRE_UPLOADED_ONLY)throw new AuthException("BOT_SUBMISSION_POLICY_MISMATCH",400);
  sandbox.verify(work(w,v));
  requireReplaceable(t,user);var existing=submission(tid,user,true);
  var now=Instant.now();var s=existing==null?new BotSubmission():existing;
  if(existing==null){
   String runtime=v.runtimeLanguage==null?w.language:v.runtimeLanguage;var lang=BotLanguage.valueOf(runtime);byte[] source=runtime.equals("JAR")?Base64.getDecoder().decode(v.source):v.source.getBytes(java.nio.charset.StandardCharsets.UTF_8);
   var upload=uploads.submissionSnapshot("Tournament bot "+user.toString().substring(0,8),lang,source);
   TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCompletion(int state){if(state==STATUS_ROLLED_BACK)uploads.discardNew(upload);}});
   var metadata=new BotMetadata(UUID.fromString(upload.id()),user,upload.name(),lang,upload.id()+"/"+lang.filename,BotMetadata.Status.READY,now,now);bots.create(metadata);
   s.id=UUID.randomUUID();s.tournamentId=tid;s.userId=user;s.registrationId=UUID.randomUUID();s.executionBotId=metadata.id();
  }
  s.versionId=v.id;s.artifactHash=v.artifactHash;s.sourceType=imported?"PRE_UPLOADED":"PLATFORM_CODED";s.status=t.botPolicy.lockOnSubmit()||automatic?"LOCKED":"SUBMITTED";s.submittedAt=now;s.lockedAt=s.status.equals("LOCKED")?now:null;
  if(existing==null)db.persist(s);v.executionBotId=s.executionBotId;v.status=s.status;w.status=s.status;w.touch();
  if(s.status.equals("LOCKED"))lockWorkspaces(tid,user);audit(tid,user,automatic?"AUTO_SUBMITTED":"BOT_SUBMITTED",v.id,null);db.flush();
  String hash=uploads.freeze(s.executionBotId.toString(),null);
  var previous=t.registrations.stream().filter(r->r.id().equals(s.registrationId)).findFirst();var status=previous.map(TournamentRegistration::status).filter(TournamentRegistrationStatus->TournamentRegistrationStatus==TournamentRegistration.Status.APPROVED).orElse(TournamentRegistration.Status.PENDING);
  return new TournamentRegistration(s.registrationId,tid,user,s.executionBotId,s.executionBotId,"Bot "+user.toString().substring(0,8),status,previous.map(TournamentRegistration::registeredAt).orElse(now),previous.map(TournamentRegistration::approvedAt).orElse(null),null).withLock(hash,now);
 }
 @Transactional public void requireReplaceable(Tournament t,UUID user){UUID tid=UUID.fromString(t.id);var existing=submission(tid,user,true);if(existing!=null){if(existing.status.equals("LOCKED"))throw new AuthException("SUBMISSION_LOCKED",409);if(existing.status.equals("REJECTED")){var reviews=db.createNativeQuery("select action from bot_submission_audit where tournament_id=:t and version_id=:v and action in ('REJECT','ALLOW-RESUBMIT') order by occurred_at desc,id desc").setParameter("t",tid).setParameter("v",existing.versionId).setMaxResults(1).getResultList();if(reviews.isEmpty()||!reviews.getFirst().equals("ALLOW-RESUBMIT"))throw new AuthException("RESUBMIT_DISABLED",409);}else if(!t.botPolicy.allowResubmitBeforeDeadline())throw new AuthException("RESUBMIT_DISABLED",409);if(existing.status.equals("DISQUALIFIED"))throw new AuthException("SUBMISSION_DISQUALIFIED",409);}if(existing==null&&t.registrations.stream().filter(TournamentRegistration::active).count()>=t.maxParticipants)throw new AuthException("PARTICIPANT_LIMIT",400);}
 private void lockWorkspaces(UUID t,UUID user){for(var w:db.createQuery("select w from CodeWorkspace w where w.tournamentId=:t and w.userId=:u",CodeWorkspace.class).setParameter("t",t).setParameter("u",user).getResultList()){w.status="LOCKED";w.touch();}}
 static WorkspaceStore.Work work(CodeWorkspace w,CodeVersion v){return new WorkspaceStore.Work(w.id,v.id,v.runtimeLanguage==null?w.language:v.runtimeLanguage,v.source,v.sourceHash,v.artifactId,v.artifactHash);}
 @Transactional public void requireLocked(String tournamentId,String participantId){if(!enabled(tournamentId))return;var matches=db.createQuery("select s from BotSubmission s where s.tournamentId=:t and s.registrationId=:r",BotSubmission.class).setParameter("t",UUID.fromString(tournamentId)).setParameter("r",UUID.fromString(participantId)).getResultList();if(matches.size()!=1||!matches.getFirst().status.equals("LOCKED"))throw new AuthException("BOT_SUBMISSION_NOT_LOCKED",409);var s=matches.getFirst();var v=db.find(CodeVersion.class,s.versionId);if(!v.status.equals("LOCKED")||!v.publicPassed||!v.pipelineSubmission&&!v.samplePassed)throw new AuthException("SUBMISSION_NOT_READY",409);if(!Objects.equals(s.artifactHash,v.artifactHash))throw new AuthException("BOT_ARTIFACT_CHANGED",409);boolean scheduled=((Number)db.createNativeQuery("select count(*) from tournament_timeline_registrations where tournament_id=:t and user_id=:u").setParameter("t",s.tournamentId).setParameter("u",s.userId).getSingleResult()).intValue()>0;if(scheduled&&db.createQuery("select count(f) from FinalValidation f,CodingFreeze c where f.freezeId=c.id and f.tournamentId=:t and f.userId=:u and f.versionId=:v and f.status='PASSED' and f.appliedAt is not null and not exists(select newer.id from CodingFreeze newer where newer.tournamentId=c.tournamentId and newer.userId=c.userId and newer.codingCloseAt>c.codingCloseAt)",Long.class).setParameter("t",s.tournamentId).setParameter("u",s.userId).setParameter("v",s.versionId).getSingleResult()!=1)throw new AuthException("FINAL_VALIDATION_REQUIRED",409);}
 @Transactional public void lockAll(String tournamentId){var t=UUID.fromString(tournamentId);for(var s:db.createQuery("select s from BotSubmission s where s.tournamentId=:t and s.status='SUBMITTED'",BotSubmission.class).setParameter("t",t).getResultList()){s.status="LOCKED";s.lockedAt=Instant.now();db.find(CodeVersion.class,s.versionId).status="LOCKED";lockWorkspaces(t,s.userId);audit(t,null,"BOT_SUBMISSION_LOCKED",s.versionId,"ROSTER_OR_DEADLINE");}}
 @Transactional public void action(String tournamentId,UUID submissionId,String action,String reason,UUID actor){var s=db.find(BotSubmission.class,submissionId,LockModeType.PESSIMISTIC_WRITE);if(s==null||!s.tournamentId.toString().equals(tournamentId))throw new AuthException("SUBMISSION_NOT_FOUND",404);if(reason==null||reason.isBlank()||reason.length()>400)throw new AuthException("REASON_REQUIRED",400);var v=db.find(CodeVersion.class,s.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId,LockModeType.PESSIMISTIC_WRITE);
  switch(action){case "lock"->{if(!s.status.equals("SUBMITTED"))throw new AuthException("INVALID_SUBMISSION_TRANSITION",409);s.status="LOCKED";s.lockedAt=Instant.now();v.status="LOCKED";lockWorkspaces(s.tournamentId,s.userId);}case "reject"->{if(s.status.equals("LOCKED")){s.status="DISQUALIFIED";lockWorkspaces(s.tournamentId,s.userId);}else{s.status="REJECTED";v.status="REJECTED";w.status="DRAFT";w.touch();}}case "allow-resubmit"->{if(!s.status.equals("REJECTED"))throw new AuthException("INVALID_SUBMISSION_TRANSITION",409);w.status="DRAFT";w.touch();}default->throw new AuthException("INVALID_ACTION",400);}audit(s.tournamentId,actor,action.toUpperCase(java.util.Locale.ROOT),v.id,reason);
 }
 private void audit(UUID t,UUID user,String action,UUID version,String reason){db.createNativeQuery("insert into bot_submission_audit(id,tournament_id,user_id,action,version_id,reason,occurred_at) values(:id,:t,:u,:a,:v,:r,:now)").setParameter("id",UUID.randomUUID()).setParameter("t",t).setParameter("u",user).setParameter("a",action).setParameter("v",version).setParameter("r",reason).setParameter("now",Instant.now()).executeUpdate();}
 @Transactional public void retest(String tournamentId,UUID submissionId,String reason,UUID actor){queue.admit();var s=db.find(BotSubmission.class,submissionId,LockModeType.PESSIMISTIC_WRITE);if(s==null||!s.tournamentId.toString().equals(tournamentId))throw new AuthException("SUBMISSION_NOT_FOUND",404);if(reason==null||reason.isBlank()||reason.length()>400)throw new AuthException("REASON_REQUIRED",400);var v=db.find(CodeVersion.class,s.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId,LockModeType.PESSIMISTIC_WRITE);if(w.busy()||!Objects.equals(w.currentVersionId,v.id))throw new AuthException("WORKSPACE_BUSY",409);v.publicPassed=false;v.samplePassed=false;v.hiddenPassed=false;v.status="TESTING";w.status="TESTING";w.touch();queue.enqueue(w,v,"VALIDATE");audit(s.tournamentId,actor,"RETEST_REQUESTED",v.id,reason);}
 @Transactional(readOnly=true) public WorkspaceStore.Work execution(String t,String registration,String botId){if(!enabled(t))return null;requireLocked(t,registration);var s=db.createQuery("select s from BotSubmission s where s.tournamentId=:t and s.registrationId=:r",BotSubmission.class).setParameter("t",UUID.fromString(t)).setParameter("r",UUID.fromString(registration)).getSingleResult();if(!s.executionBotId.toString().equals(botId))throw new AuthException("BOT_ARTIFACT_CHANGED",409);var v=db.find(CodeVersion.class,s.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId);return work(w,v);}
 @Transactional(readOnly=true) public UUID latestReady(String t,UUID user){return db.createQuery("select v.id from CodeVersion v,CodeWorkspace w where v.workspaceId=w.id and w.tournamentId=:t and w.userId=:u and v.status='READY' order by v.createdAt desc",UUID.class).setParameter("t",UUID.fromString(t)).setParameter("u",user).setMaxResults(1).getResultStream().findFirst().orElse(null);}
 @Transactional(readOnly=true) public boolean newerThanSubmission(UUID version,Summary s){return s==null||s.status().equals("SUBMITTED")&&db.find(CodeVersion.class,version).createdAt.isAfter(s.submittedAt());}
 @Transactional(readOnly=true) public boolean deadlineDone(String id){return ((Number)db.createNativeQuery("select count(*) from tournament_submission_deadlines where tournament_id=:t").setParameter("t",UUID.fromString(id)).getSingleResult()).intValue()>0;}
 @Transactional public void finishDeadline(String id){if(!deadlineDone(id))db.createNativeQuery("insert into tournament_submission_deadlines(tournament_id,processed_at) values(:t,:now)").setParameter("t",UUID.fromString(id)).setParameter("now",Instant.now()).executeUpdate();}
 @Transactional public void autoRejected(String id,UUID user){audit(UUID.fromString(id),user,"AUTO_SUBMIT_REJECTED",null,"No eligible slot, account or version at deadline");}
 @Transactional(readOnly=true) public List<UUID> readyUsers(String t){return db.createQuery("select distinct w.userId from CodeWorkspace w,CodeVersion v where v.workspaceId=w.id and w.tournamentId=:t and v.status='READY'",UUID.class).setParameter("t",UUID.fromString(t)).getResultList();}

 @Transactional(readOnly=true) public CodingFreeze.View frozenMine(String id,UUID user,Instant cutoff){var rows=db.createQuery("select f from CodingFreeze f where f.tournamentId=:t and f.userId=:u and f.codingCloseAt=:c",CodingFreeze.class).setParameter("t",UUID.fromString(id)).setParameter("u",user).setParameter("c",cutoff).getResultList();return rows.isEmpty()?null:rows.getFirst().view();}
 /** Keyset-like work admission: completed rows disappear from this bounded query. */
 @Transactional(readOnly=true) public List<UUID> pendingFreezeUsers(String id,Instant cutoff,int limit){return db.createNativeQuery("select r.user_id from tournament_timeline_registrations r where r.tournament_id=:t and r.status='APPROVED' and not exists (select 1 from tournament_coding_freezes f where f.tournament_id=r.tournament_id and f.user_id=r.user_id and f.coding_close_at=:c) order by r.user_id",UUID.class).setParameter("t",UUID.fromString(id)).setParameter("c",cutoff).setMaxResults(limit).getResultList();}
 public record FreezeResult(CodingFreeze.View freeze,TournamentRegistration registration){}
 @Transactional public FreezeResult freezeAtDeadline(Tournament t,UUID user,boolean active,Instant now){return freezeAtDeadline(t,user,active,now,t.timeline.codingCloseAt(),false);}
 @Transactional public FreezeResult freezeAtDeadline(Tournament t,UUID user,boolean active,Instant now,Instant cutoff,boolean emergency){
  UUID tid=UUID.fromString(t.id);
  db.createNativeQuery("select id from users where id=:u for update").setParameter("u",user).getSingleResult();
  var previous=frozenMine(t.id,user,cutoff);if(previous!=null)return new FreezeResult(previous,null);
  if(now.isBefore(cutoff))throw new AuthException("CODING_STILL_OPEN",409);
  var old=submission(tid,user,true);TournamentRegistration registration=null;String decision="EXPLICIT_SUBMIT",reason=null;
  boolean reopened=old!=null&&old.status.equals("REJECTED")&&t.operations.audit().stream().anyMatch(a->a.type().equals("TIMELINE_OVERRIDE_EXTEND_CODING"));
  boolean eligible=active&&(old==null||Set.of("SUBMITTED","LOCKED").contains(old.status)||(emergency||reopened)&&old.status.equals("REJECTED"));
  if(eligible&&t.timeline.deadlinePolicy()==TournamentTimeline.DeadlinePolicy.AUTO_SUBMIT_LATEST_READY&&(old==null||(emergency||reopened)&&old.status.equals("REJECTED")||old.status.equals("SUBMITTED")&&t.botPolicy.allowResubmitBeforeDeadline())){
   var candidates=db.createQuery("select v from CodeVersion v,CodeWorkspace w where v.workspaceId=w.id and w.tournamentId=:t and w.userId=:u and v.status='READY' and v.createdAt<:c and v.updatedAt<:c order by v.createdAt desc,v.id desc",CodeVersion.class).setParameter("t",tid).setParameter("u",user).setParameter("c",cutoff).setMaxResults(1).getResultList();
   if(!candidates.isEmpty()){
    var v=candidates.getFirst();var existingVersion=old==null?null:db.find(CodeVersion.class,old.versionId);
    if(existingVersion==null||v.createdAt.isAfter(existingVersion.createdAt)){
     var w=db.find(CodeWorkspace.class,v.workspaceId);
     try{sandbox.verify(work(w,v));}catch(WorkspaceSandbox.Failure invalid){eligible=false;reason="ARTIFACT_CHANGED";}
     if(eligible){registration=promote(t,user,v.id,true,true);old=submission(tid,user,true);decision="AUTO_SUBMITTED";}
    }
   }
  }
  boolean hasSubmission=eligible&&old!=null&&!old.submittedAt.isAfter(cutoff)&&Set.of("SUBMITTED","LOCKED").contains(old.status);
  // Automatic promotion occurs after the cutoff, but selects only READY facts from before it.
  if(registration!=null)hasSubmission=true;
  var f=new CodingFreeze();f.id=UUID.randomUUID();f.tournamentId=tid;f.userId=user;f.codingCloseAt=cutoff;f.frozenAt=now;
  if(hasSubmission){
   var v=db.find(CodeVersion.class,old.versionId);var w=db.find(CodeWorkspace.class,v.workspaceId);
   if(!Objects.equals(old.artifactHash,v.artifactHash)){hasSubmission=false;reason="ARTIFACT_CHANGED";}
   if(hasSubmission&&registration==null)try{sandbox.verify(work(w,v));}catch(WorkspaceSandbox.Failure invalid){hasSubmission=false;reason="ARTIFACT_CHANGED";}
   if(hasSubmission){old.status="LOCKED";old.lockedAt=now;v.status="LOCKED";lockWorkspaces(tid,user);f.decision=decision;f.versionId=v.id;f.versionNumber=v.number;f.language=w.language;f.sourceHash=v.sourceHash;f.artifactHash=old.artifactHash;f.submittedAt=old.submittedAt;}
  }
  if(!hasSubmission){f.decision="MISSING";f.reason=reason!=null?reason:!active?"ACCOUNT_INACTIVE":!eligible?"SUBMISSION_REJECTED":t.timeline.deadlinePolicy()==TournamentTimeline.DeadlinePolicy.REQUIRE_EXPLICIT_SUBMIT?"EXPLICIT_SUBMIT_REQUIRED":"NO_READY_VERSION_BEFORE_DEADLINE";}
  db.persist(f);audit(tid,user,"CODING_DEADLINE_FROZEN",f.versionId,f.decision+(f.reason==null?"":":"+f.reason));db.flush();return new FreezeResult(f.view(),registration);
 }
}
